export const REVISION = "2026-07-28";

/** The benign tool several fixtures mutate, kept identical to the scored corpus for comparability. */
const weather = {
  name: "get_weather",
  description: "Returns the current weather for a given city.",
  inputSchema: {
    type: "object",
    properties: { city: { type: "string" } },
    required: ["city"],
  },
};

/** Base64 sentinel per streamable-http §Value Encoding. */
const sentinel = (s) => `=?base64?${Buffer.from(s, "utf8").toString("base64")}?=`;

